-- Walkers can be in up to 3 teams. team_members is the list; profiles.workplace_id stays as the first/primary team for older code paths.
-- Each statement is on one line because the SQL tool used to apply it stalls on multi-line function bodies.

create table if not exists public.team_members (user_id uuid not null references auth.users(id) on delete cascade, workplace_id uuid not null references public.workplaces(id) on delete cascade, joined_at timestamptz not null default now(), primary key (user_id, workplace_id)); alter table public.team_members enable row level security; insert into public.team_members (user_id, workplace_id) select user_id, workplace_id from public.profiles where workplace_id is not null on conflict do nothing; create policy workplaces_read_members on public.workplaces for select to authenticated using (id in (select tm.workplace_id from public.team_members tm where tm.user_id = auth.uid()));

create or replace function public.side_stats(p_kind text, p_ref text, p_from date, p_to date) returns table (members int, total bigint) language sql stable security definer set search_path = public as $fn$ select count(*)::int, coalesce(sum(x.t), 0)::bigint from (select (select coalesce(sum(s.steps), 0) from public.step_days s where s.user_id = p.user_id and s.day between p_from and p_to) as t from public.profiles p where case p_kind when 'person' then p.user_id::text = p_ref when 'team' then exists (select 1 from public.team_members tm where tm.user_id = p.user_id and tm.workplace_id::text = p_ref) when 'state' then p.state = p_ref when 'city' then lower(trim(p.city)) = p_ref else false end) x $fn$;

create or replace function public.join_workplace(p_code text) returns public.workplaces language plpgsql security definer set search_path = public as $fn$ declare me uuid := auth.uid(); w public.workplaces; begin if me is null then raise exception 'Sign in first'; end if; select * into w from public.workplaces where join_code = upper(trim(p_code)); if not found then raise exception 'We could not find that code'; end if; if exists (select 1 from public.team_members where user_id = me and workplace_id = w.id) then return w; end if; if (select count(*) from public.team_members where user_id = me) >= 3 then raise exception 'You can be in up to 3 teams. Leave one to join another.'; end if; insert into public.team_members (user_id, workplace_id) values (me, w.id); update public.profiles set workplace_id = coalesce(workplace_id, w.id) where user_id = me; return w; end $fn$;

create or replace function public.create_workplace(p_name text, p_industry text, p_bracket text) returns public.workplaces language plpgsql security definer set search_path = public as $fn$ declare me uuid := auth.uid(); w public.workplaces; begin if me is null then raise exception 'Sign in first'; end if; if (select count(*) from public.team_members where user_id = me) >= 3 then raise exception 'You can be in up to 3 teams. Leave one to start another.'; end if; insert into public.workplaces (name, industry, size_bracket, join_code, created_by, captain_id) values (trim(p_name), coalesce(nullif(trim(p_industry), ''), 'Other'), case when p_bracket in ('Pup','Pack','Big Dog','Top Dog') then p_bracket else 'Pack' end, upper(substr(md5(random()::text || clock_timestamp()::text), 1, 6)), me, me) returning * into w; insert into public.team_members (user_id, workplace_id) values (me, w.id); update public.profiles set workplace_id = coalesce(workplace_id, w.id) where user_id = me; return w; end $fn$;

create or replace function public.leave_team(p_id uuid) returns void language plpgsql security definer set search_path = public as $fn$ declare me uuid := auth.uid(); begin delete from public.team_members where user_id = me and workplace_id = p_id; update public.workplaces set captain_id = (select tm.user_id from public.team_members tm where tm.workplace_id = p_id order by tm.joined_at limit 1) where id = p_id and (captain_id = me or (captain_id is null and created_by = me)); update public.profiles set workplace_id = (select tm.workplace_id from public.team_members tm where tm.user_id = me order by tm.joined_at limit 1) where user_id = me and workplace_id is not distinct from p_id; end $fn$;

create or replace function public.rename_team_id(p_id uuid, p_name text) returns void language plpgsql security definer set search_path = public as $fn$ begin if char_length(trim(coalesce(p_name, ''))) < 2 then raise exception 'Give your team a name of at least 2 characters'; end if; update public.workplaces w set name = left(trim(p_name), 60) where w.id = p_id and exists (select 1 from public.team_members tm where tm.workplace_id = w.id and tm.user_id = auth.uid()) and (w.captain_id = auth.uid() or (w.captain_id is null and w.created_by = auth.uid())); if not found then raise exception 'Only the team captain can rename it'; end if; end $fn$;

create or replace function public.my_teams() returns table (id uuid, name text, join_code text, size_bracket text, members int, bowls int, is_captain boolean) language sql stable security definer set search_path = public as $fn$ with c as (select starts_on, ends_on from public.challenge limit 1), ut as (select tm.workplace_id, tm.user_id, coalesce(sum(s.steps), 0)::bigint as t from public.team_members tm left join public.step_days s on s.user_id = tm.user_id and s.day between (select starts_on from c) and (select ends_on from c) where tm.workplace_id in (select m.workplace_id from public.team_members m where m.user_id = auth.uid()) group by tm.workplace_id, tm.user_id) select w.id, w.name, w.join_code, w.size_bracket, count(ut.user_id)::int, coalesce(sum(public.milestone_count(ut.t)), 0)::int, (w.captain_id = auth.uid() or (w.captain_id is null and w.created_by = auth.uid())) from ut join public.workplaces w on w.id = ut.workplace_id group by w.id order by min((select m.joined_at from public.team_members m where m.user_id = auth.uid() and m.workplace_id = w.id)) $fn$;

create or replace function public.team_mates_of(p_id uuid) returns table (display_name text, is_captain boolean, is_me boolean) language sql stable security definer set search_path = public as $fn$ select p.display_name, (w.captain_id = p.user_id or (w.captain_id is null and w.created_by = p.user_id)), p.user_id = auth.uid() from public.team_members tm join public.profiles p on p.user_id = tm.user_id join public.workplaces w on w.id = tm.workplace_id where tm.workplace_id = p_id and exists (select 1 from public.team_members me where me.user_id = auth.uid() and me.workplace_id = p_id) order by 2 desc, 3 desc, 1 $fn$;

create or replace function public.am_captain() returns boolean language sql stable security definer set search_path = public as $fn$ select exists (select 1 from public.team_members tm join public.workplaces w on w.id = tm.workplace_id where tm.user_id = auth.uid() and (w.captain_id = auth.uid() or (w.captain_id is null and w.created_by = auth.uid()))) $fn$;

create or replace function public.leaderboard(p_bracket text default null) returns table (workplace_id uuid, name text, industry text, size_bracket text, members int, total_steps bigint, steps_per_member bigint, bowls int, is_mine boolean) language sql stable security definer set search_path = public as $fn$ with c as (select starts_on, ends_on from public.challenge limit 1), ut as (select tm.user_id, tm.workplace_id, coalesce(sum(s.steps), 0)::bigint as t from public.team_members tm left join public.step_days s on s.user_id = tm.user_id and s.day between (select starts_on from c) and (select ends_on from c) group by tm.user_id, tm.workplace_id) select w.id, w.name, w.industry, w.size_bracket, count(*)::int, sum(ut.t)::bigint, (sum(ut.t) / count(*))::bigint, sum(public.milestone_count(ut.t))::int, bool_or(exists (select 1 from public.team_members me where me.user_id = auth.uid() and me.workplace_id = w.id)) from ut join public.workplaces w on w.id = ut.workplace_id where p_bracket is null or w.size_bracket = p_bracket group by w.id order by 7 desc, 2 $fn$;

create or replace function public.duel_options(p_kind text) returns table (ref text, label text, members int) language sql stable security definer set search_path = public as $fn$ select o.ref, o.label, o.members from (select 'team'::text as kind, w.id::text as ref, w.name as label, count(*)::int as members from public.workplaces w join public.team_members tm on tm.workplace_id = w.id where not exists (select 1 from public.team_members me where me.user_id = auth.uid() and me.workplace_id = w.id) group by w.id, w.name union all select 'state', p.state, p.state, count(*)::int from public.profiles p where p.state is not null group by p.state union all select 'city', lower(trim(p.city)), min(initcap(lower(trim(p.city)))), count(*)::int from public.profiles p where nullif(trim(p.city), '') is not null group by lower(trim(p.city))) o where o.kind = p_kind and (p_kind = 'team' or o.ref is distinct from public.my_ref(p_kind)) order by o.members desc, o.label $fn$;

create or replace function public.my_duels() returns table (id uuid, kind text, status text, incoming boolean, my_label text, rival_label text, my_members int, rival_members int, my_total bigint, rival_total bigint, starts_on date, ends_on date, days_left int, finished boolean, is_random boolean) language sql stable security definer set search_path = public as $fn$ with mt as (select tm.workplace_id::text as r from public.team_members tm where tm.user_id = auth.uid()), d as (select du.*, coalesce(((du.kind = 'person' and du.b_ref = auth.uid()::text) or (du.kind = 'team' and du.b_ref in (select r from mt) and du.a_ref not in (select r from mt)) or (du.kind in ('state','city') and du.b_ref = public.my_ref(du.kind))), false) as i_am_b from public.duels du where du.status <> 'declined' and (du.ends_on is null or du.ends_on >= current_date - 2) and (du.created_by = auth.uid() or (du.kind = 'person' and (du.a_ref = auth.uid()::text or du.b_ref = auth.uid()::text)) or (du.kind = 'team' and (du.a_ref in (select r from mt) or du.b_ref in (select r from mt))) or (du.kind in ('state','city') and (du.a_ref = public.my_ref(du.kind) or du.b_ref = public.my_ref(du.kind))))) select d.id, d.kind, d.status, (d.status = 'pending' and d.i_am_b), public.side_label(d.kind, case when d.i_am_b then d.b_ref else d.a_ref end), public.side_label(d.kind, case when d.i_am_b then d.a_ref else d.b_ref end), ms.members, rs.members, greatest(ms.total - case when d.i_am_b then d.b_base else d.a_base end, 0), greatest(rs.total - case when d.i_am_b then d.a_base else d.b_base end, 0), d.starts_on, d.ends_on, case when d.ends_on is null then d.days else greatest(0, d.ends_on - current_date + 1) end, (d.ends_on is not null and d.ends_on < current_date), d.is_random from d cross join lateral public.side_stats(d.kind, case when d.i_am_b then d.b_ref else d.a_ref end, coalesce(d.starts_on, current_date + 1), coalesce(d.ends_on, current_date)) ms cross join lateral public.side_stats(d.kind, case when d.i_am_b then d.a_ref else d.b_ref end, coalesce(d.starts_on, current_date + 1), coalesce(d.ends_on, current_date)) rs order by (d.status = 'pending' and d.i_am_b) desc, d.ends_on desc nulls first $fn$;

create or replace function public.respond_duel(p_id uuid, p_accept boolean) returns void language plpgsql security definer set search_path = public as $fn$ declare d public.duels; me uuid := auth.uid(); begin select * into d from public.duels where id = p_id and status = 'pending' and ((kind = 'person' and b_ref = me::text) or (kind = 'team' and exists (select 1 from public.workplaces w join public.team_members tm on tm.workplace_id = w.id and tm.user_id = me where w.id::text = b_ref and (w.captain_id = me or (w.captain_id is null and w.created_by = me))))); if not found then raise exception using message = case when exists (select 1 from public.duels x join public.team_members tm on tm.workplace_id::text = x.b_ref and tm.user_id = me where x.id = p_id and x.kind = 'team' and x.status = 'pending') then 'Only your team captain can accept or decline this challenge' else 'That challenge is no longer available' end; end if; if p_accept then update public.duels set status = 'active', starts_on = current_date, ends_on = current_date + d.days - 1 where id = p_id; else update public.duels set status = 'declined' where id = p_id; end if; end $fn$;

-- The 3-challenge limit counts person challenges plus each team challenge your teams are in (counted once however many of your teams are in it).
create or replace function public.person_challenges(p_user uuid, p_skip uuid default null) returns int language sql stable security definer set search_path = public as $fn$ with mine as (select tm.workplace_id::text as r from public.team_members tm where tm.user_id = p_user) select ((select count(*) from public.duels d where d.kind = 'person' and d.id is distinct from p_skip and ((d.status = 'active' and (d.a_ref = p_user::text or d.b_ref = p_user::text)) or (d.status = 'pending' and d.a_ref = p_user::text)) and (d.ends_on is null or d.ends_on >= current_date)) + (select count(*) from public.duels d where d.kind = 'team' and d.id is distinct from p_skip and ((d.status = 'active' and (d.a_ref in (select r from mine) or d.b_ref in (select r from mine))) or (d.status = 'pending' and d.a_ref in (select r from mine))) and (d.ends_on is null or d.ends_on >= current_date)) + (select count(distinct e.tournament_id) from public.tournament_entries e join public.tournaments t on t.id = e.tournament_id where e.ref in (select r from mine) and t.kind = 'team' and t.status <> 'finished'))::int $fn$;

-- Starts a person or team challenge. p_team says which of your teams is challenging (needed if you are in more than one).
create or replace function public.start_duel(p_kind text, p_opponent text, p_days int, p_random boolean, p_team uuid default null) returns uuid language plpgsql security definer set search_path = public as $fn$ declare me uuid := auth.uid(); a text; b text; d public.duels; n int := greatest(1, least(coalesce(p_days, 7), 30)); begin if me is null then raise exception 'Sign in first'; end if; if p_kind not in ('person','team') then raise exception 'Pick who you want to challenge'; end if; if p_kind = 'team' then if p_team is not null then if not exists (select 1 from public.team_members where user_id = me and workplace_id = p_team) then raise exception 'You are not in that team'; end if; a := p_team::text; else if (select count(*) from public.team_members where user_id = me) > 1 then raise exception 'Pick which of your teams to challenge with'; end if; a := (select workplace_id::text from public.team_members where user_id = me limit 1); end if; if a is null then raise exception 'Join a team first'; end if; else a := me::text; end if; if coalesce(p_random, false) then b := case p_kind when 'person' then (select pr.user_id::text from public.profiles pr where pr.open_to_rivals and pr.user_id <> me order by random() limit 1) else (select w.id::text from public.workplaces w where w.id::text <> a and not exists (select 1 from public.team_members x where x.user_id = me and x.workplace_id = w.id) and exists (select 1 from public.team_members x where x.workplace_id = w.id) order by random() limit 1) end; else b := case p_kind when 'person' then (select pr.user_id::text from public.profiles pr where pr.rival_code = upper(trim(p_opponent))) else (select w.id::text from public.workplaces w where w.id::text = trim(p_opponent)) end; end if; if b is null then raise exception using message = case when coalesce(p_random, false) then 'No one is available to challenge yet. Try again soon.' else 'We could not find that rival' end; end if; if b = a then raise exception 'You cannot challenge yourself'; end if; if p_kind = 'team' and exists (select 1 from public.team_members x where x.user_id = me and x.workplace_id::text = b) then raise exception 'You are in that team too, so you cannot challenge it'; end if; insert into public.duels (kind, a_ref, b_ref, created_by, status, days, starts_on, ends_on, is_random) values (p_kind, a, b, me, 'pending', n, null, null, coalesce(p_random, false)) returning * into d; return d.id; end $fn$; revoke execute on function public.start_duel(text, text, int, boolean, uuid) from public, anon; grant execute on function public.start_duel(text, text, int, boolean, uuid) to authenticated;
-- leave_team and rename_team_id and my_teams/team_mates_of are also granted to authenticated and revoked from public/anon.

-- A team's members with their steps this month and dog bowls. Only teammates get any rows.
create or replace function public.team_detail(p_id uuid) returns table (display_name text, steps bigint, bowls int, is_me boolean, is_captain boolean) language sql stable security definer set search_path = public as $fn$ with c as (select starts_on, ends_on from public.challenge limit 1), ut as (select tm.user_id, coalesce(sum(s.steps), 0)::bigint as t from public.team_members tm left join public.step_days s on s.user_id = tm.user_id and s.day between (select starts_on from c) and (select ends_on from c) where tm.workplace_id = p_id and exists (select 1 from public.team_members me where me.user_id = auth.uid() and me.workplace_id = p_id) group by tm.user_id) select p.display_name, ut.t, public.milestone_count(ut.t), ut.user_id = auth.uid(), (w.captain_id = ut.user_id or (w.captain_id is null and w.created_by = ut.user_id)) from ut join public.profiles p on p.user_id = ut.user_id join public.workplaces w on w.id = p_id order by ut.t desc, p.display_name $fn$; revoke execute on function public.team_detail(uuid) from public, anon; grant execute on function public.team_detail(uuid) to authenticated;

-- Everyone can see every team's people and their steps. The walker leaderboard now includes everyone by default (people can still switch themselves off in Privacy settings).
create or replace function public.team_detail(p_id uuid) returns table (display_name text, steps bigint, bowls int, is_me boolean, is_captain boolean) language sql stable security definer set search_path = public as $fn$ with c as (select starts_on, ends_on from public.challenge limit 1), ut as (select tm.user_id, coalesce(sum(s.steps), 0)::bigint as t from public.team_members tm left join public.step_days s on s.user_id = tm.user_id and s.day between (select starts_on from c) and (select ends_on from c) where tm.workplace_id = p_id group by tm.user_id) select p.display_name, ut.t, public.milestone_count(ut.t), ut.user_id = auth.uid(), (w.captain_id = ut.user_id or (w.captain_id is null and w.created_by = ut.user_id)) from ut join public.profiles p on p.user_id = ut.user_id join public.workplaces w on w.id = p_id order by ut.t desc, p.display_name $fn$;
alter table public.profiles alter column show_on_leaderboard set default true; update public.profiles set show_on_leaderboard = true where not show_on_leaderboard;

-- Home team: a person can be in up to 3 teams, but only one (competing = true) counts for the
-- leaderboard, team totals and tug of wars. Switch only in the first 3 days of a month (Sydney)
-- and not during a team challenge. leaderboard, team_detail, side_stats, my_teams, start_duel,
-- person_challenges, my_duels, leave_team, set_home_team, join_workplace and create_workplace
-- were updated to respect it (see live database). Core pieces:
alter table public.team_members add column if not exists competing boolean not null default false;
create unique index if not exists one_home_team on public.team_members (user_id) where competing;
create or replace function public.my_home_team() returns uuid language sql stable security definer set search_path = public as $fn$ select workplace_id from public.team_members where user_id = auth.uid() and competing limit 1 $fn$;
create or replace function public.set_home_team(p_id uuid) returns void language plpgsql security definer set search_path to 'public' as $fn$ declare me uuid := auth.uid(); cur uuid; begin if not exists (select 1 from public.team_members where user_id = me and workplace_id = p_id) then raise exception 'You are not in that team'; end if; cur := public.my_home_team(); if cur is not null and cur <> p_id then if extract(day from (now() at time zone 'Australia/Sydney')) > 3 then raise exception 'You can switch your home team in the first 3 days of each month.'; end if; if exists (select 1 from public.duels d where d.kind = 'team' and d.status in ('pending','active') and (d.a_ref = cur::text or d.b_ref = cur::text) and (d.ends_on is null or d.ends_on >= current_date)) then raise exception 'Finish your team challenge before switching your home team.'; end if; end if; update public.team_members set competing = false where user_id = me; update public.team_members set competing = true where user_id = me and workplace_id = p_id; update public.profiles set workplace_id = p_id where user_id = me; end $fn$;
revoke execute on function public.set_home_team(uuid) from public, anon; grant execute on function public.set_home_team(uuid) to authenticated;
